CREATE OR REPLACE FUNCTION private.assert_org_role_references_v1(p_org_id uuid, p_role_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform private.personnel_lock_org_v1(p_org_id);
  if exists (
    select 1 from unnest(p_role_ids) as requested(role_id)
    where not exists (select 1 from private.org_role_catalog_v1(p_org_id, false) as catalog where catalog.id = requested.role_id)
  ) then
    raise exception 'organization role does not exist' using errcode = '23503', detail = 'ORG_ROLE_NOT_FOUND';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_system_role_assignment_actor_v1(p_actor_id uuid, p_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform private.personnel_lock_org_v1(p_org_id);
  perform 1 from public.organizations where id = p_org_id for no key update;
  if not private.personnel_is_org_control_admin_v1(p_actor_id, p_org_id) then
    raise exception 'only the current system administrator can change role assignments'
      using errcode = '42501';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.reject_org_super_admin_invitation_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' then
    -- The original creator is historical data, not the actor of an update.
    -- Existing pending invitations may be reissued, accepted or revoked.
    if new.status = 'pending' and cardinality(new.role_ids) > 0 and (
      not (new.role_ids <@ old.role_ids)
      or new.org_id is distinct from old.org_id
      or new.user_id is distinct from old.user_id
      or old.status is distinct from 'pending'
    ) then
      raise exception 'new role reservations require a new invitation'
        using errcode = '42501', detail = 'PERSONNEL_INVITATION_ROLE_CHANGE_FORBIDDEN';
    end if;
    if new.role_ids is not distinct from old.role_ids then return new; end if;
  end if;

  if exists (select 1 from public.roles where code in ('SUPER_ADMIN', 'ORG_SUPER_ADMIN') and id = any(new.role_ids)) then
    raise exception 'system administrator cannot be appointed through an invitation' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' and cardinality(new.role_ids) > 0 then
    begin
      perform private.assert_system_role_assignment_actor_v1(new.created_by, new.org_id);
    exception when insufficient_privilege then
      raise exception 'only the current system administrator can reserve roles on an invitation'
        using errcode = '42501', detail = 'PERSONNEL_INVITATION_ROLE_AUTHORITY_REQUIRED';
    end;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_org_personnel_invitation_roles_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status <> 'pending' or cardinality(new.role_ids) = 0 then return new; end if;
  if tg_op = 'UPDATE' and new.status is not distinct from old.status
    and new.org_id is not distinct from old.org_id and new.role_ids is not distinct from old.role_ids then
    return new;
  end if;
  perform private.assert_org_role_references_v1(new.org_id, new.role_ids);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_user_role_scope_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1
    from public.user_organizations as membership
    where membership.user_id = new.user_id
      and membership.org_id = new.org_id
      and membership.status = 'active'
  ) then
    raise exception 'user role requires an active organization membership';
  end if;

  if new.scope_type = 'org' then
    if new.scope_id is not null and new.scope_id <> new.org_id then
      raise exception 'organization role scope does not match membership tenant';
    end if;
  elsif new.scope_type = 'department' then
    if new.scope_id is not null and not exists (
      select 1
      from public.departments as department
      where department.id = new.scope_id
        and department.org_id = new.org_id
    ) then
      raise exception 'department role scope does not match membership tenant';
    end if;
  elsif new.scope_type = 'space' then
    if new.scope_id is not null and not exists (
      select 1
      from public.sales_spaces as space
      where space.id = new.scope_id
        and space.org_id = new.org_id
    ) then
      raise exception 'space role scope does not match membership tenant';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_department_path()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare parent_path text;
begin
  if new.parent_id is null then
    new.path := '/' || new.id::text || '/';
    new.depth := 0;
  else
    select path, depth into parent_path, new.depth
      from public.departments where id = new.parent_id;
    new.path := parent_path || new.id::text || '/';
    new.depth := new.depth + 1;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_dept_member_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    update public.departments set member_count = member_count + 1 where id = new.department_id;
  elsif tg_op = 'DELETE' then
    update public.departments set member_count = greatest(member_count - 1, 0) where id = old.department_id;
  end if;
  return null;
end;
$function$
